// ═══ Java 9: List.of() — truly immutable ═══
List<String> immutable = List.of("SAV2001", "CUR3001", "FD4001");
// immutable.add("X");     → UnsupportedOperationException!
// immutable.set(0, "X");  → UnsupportedOperationException!
// immutable.remove(0);    → UnsupportedOperationException!
// List.of(null);           → NullPointerException! No nulls allowed!

Set<String> immutableSet = Set.of("SAV2001", "CUR3001");
// Set.of("A", "A");  → IllegalArgumentException! No duplicates!

Map<String, Integer> immutableMap = Map.of("SAV2001", 75000, "CUR3001", 120000);
// Max 10 key-value pairs with Map.of(). For more:
Map<String, Integer> bigMap = Map.ofEntries(
    Map.entry("SAV2001", 75000),
    Map.entry("CUR3001", 120000),
    Map.entry("FD4001", 500000)
);

// ═══ Collections.unmodifiableList — VIEW, not copy! ═══
List<String> original = new ArrayList<>(List.of("A", "B"));
List<String> view = Collections.unmodifiableList(original);
// view.add("C");  → UnsupportedOperationException! (view is unmodifiable)
original.add("C");  // BUT: original CAN still be modified!
view.size();         // 3! The view REFLECTS the change! NOT truly immutable!

// ═══ Java 10: List.copyOf — defensive copy ═══
List<String> mutable = new ArrayList<>(List.of("A", "B"));
List<String> copy = List.copyOf(mutable);  // creates SEPARATE immutable copy
mutable.add("C");   // modify original
copy.size();         // 2! Copy is UNAFFECTED! Truly immutable snapshot!
```

