// ─── File: src/test/java/com/bank/immutable/ImmutableFactoryTest.java ───
package com.bank.immutable;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class ImmutableFactoryTest {

    @Test
    void listOf_trulyImmutable() {
        List<String> list = List.of("SAV2001", "CUR3001");
        assertThatThrownBy(() -> list.add("FD4001"))
            .isInstanceOf(UnsupportedOperationException.class);
        assertThatThrownBy(() -> list.set(0, "X"))
            .isInstanceOf(UnsupportedOperationException.class);
    }

    @Test
    void listOf_rejectsNull() {
        assertThatThrownBy(() -> List.of("A", null))
            .isInstanceOf(NullPointerException.class);
    }

    @Test
    void setOf_rejectsDuplicates() {
        assertThatThrownBy(() -> Set.of("A", "A"))
            .isInstanceOf(IllegalArgumentException.class);
    }

    @Test
    void unmodifiableList_isView_notCopy() {
        List<String> original = new ArrayList<>(List.of("A", "B"));
        List<String> view = Collections.unmodifiableList(original);
        assertThat(view).hasSize(2);

        original.add("C");  // modify ORIGINAL!
        assertThat(view).hasSize(3);  // view REFLECTS change! NOT immutable!
    }

    @Test
    void listCopyOf_defensiveCopy() {
        List<String> mutable = new ArrayList<>(List.of("A", "B"));
        List<String> copy = List.copyOf(mutable);
        assertThat(copy).hasSize(2);

        mutable.add("C");  // modify original
        assertThat(copy).hasSize(2);  // copy UNAFFECTED! True snapshot!
    }

    @Test
    void mapOf_immutable() {
        Map<String, Integer> map = Map.of("SAV2001", 75000, "CUR3001", 120000);
        assertThatThrownBy(() -> map.put("FD4001", 500000))
            .isInstanceOf(UnsupportedOperationException.class);
    }
}
```

sections.s5d_lld:
```
   List.of(E...)            → ImmutableCollections.ListN  (no src ref)
   List.copyOf(Collection)  → new ListN(src.toArray())    (independent)
   Collections.unmodifiableList(src)
       → UnmodifiableList { final List<E> list = src;      // HOLDS src!
             add/set/remove → UnsupportedOperationException
             get(i)         → list.get(i)  // sees src mutations }

   class AccountApi
     - List<Account> internal = new ArrayList<>();
     // GOOD — independent snapshot
     + List<Account> safe()  { return List.copyOf(internal); }
     // RISKY — view still backed by internal
     + List<Account> leaky() { return Collections.unmodifiableList(internal); }
   // internal.add(x): safe() unaffected; leaky() silently shows x
```
